function_name: NOVO.transferFrom
code: function transferFrom(
    address sender,
    address recipient,
    uint256 amount
) public override returns (bool) {
    uint256 lockedAmount = getLockedAmount(sender);
    if (lockedAmount > 0) {
        require(
            (balanceOf(sender) - amount) >= lockedAmount,
            "Your balance was locked"
        );
    }
    _transfer(sender, recipient, amount);
    if (recipient == address(uniswapV2Router)) {
        uint256 rewards = _novoNFT.getReward(sender);
        if (rewards > 0) {
            _transfer(_stakingPoolAddress, sender, rewards);
        }
    }
    return true;
}
vulnerability: Missing allowance check in transferFrom
reason: The function overrides ERC20 transferFrom but never checks or decreases the allowance of msg.sender for sender. Any external account can call transferFrom(victim, attacker, amount) to transfer any amount of NOVO from a victim who has not approved the caller. The internal _transfer only enforces lock and blacklist checks and then moves tokens, so this is directly exploitable to steal all unlocked NOVO from any holder.
------------------
function_name: NovoNFT.getReward
code: function getReward(address _address) public returns (uint256) {
    require(
        msg.sender == address(novo),
        "This function should be called by NOVO"
    );
    uint256[] memory tokenIds = walletOfOwner(_address);
    uint256 _bagSizeReward = 0;
    uint256 _stakingTimeReward = 0;
    uint256 totalStakingTime = 0;
    uint256 totalRewardOfAddress = 0;
    totalStakingTime = uint80(block.timestamp - baseTimestamp) * stakingNFTs.length - totalDiffTimestamp;
    uint256 _curRemainReward = novo.balanceOf(address(this)) / 2;
    for (uint256 i = 0; i < tokenIds.length; i++) {
        _bagSizeReward = (_curRemainReward * getLockedAmountByTokenId(tokenIds[i])) / totalBagSize;
        _stakingTimeReward = (_curRemainReward * (uint80(block.timestamp) - mapStakers[tokenIds[i]].stakingTimestamp)) / totalStakingTime;
        mapStakers[tokenIds[i]].bagSizeReward += _bagSizeReward;
        mapStakers[tokenIds[i]].stakingTimeReward += _stakingTimeReward;
        totalRewardOfAddress += _bagSizeReward + _stakingTimeReward;
    }
    totalBagSize += totalRewardOfAddress;
    return totalRewardOfAddress;
}
vulnerability: Reward double-claim due to missing timestamp update and wrong balance source
reason: getReward calculates _stakingTimeReward using the full elapsed time since mapStakers[tokenId].stakingTimestamp on every call, but never updates that timestamp or subtracts already-claimed time. Because NOVO.transfer and NOVO.transferFrom call getReward whenever the recipient is the Uniswap router, an attacker can repeatedly trigger getReward in the same or later blocks and receive the same time-based reward over and over. Additionally, _curRemainReward is read from novo.balanceOf(address(this)) (the NFT contract) rather than the actual staking pool, and this balance is not reduced by claims. An attacker can send a small amount of NOVO to the NFT contract to make reward calculations nonzero and then repeatedly drain real NOVO from _stakingPoolAddress whenever rewards are paid.
------------------
function_name: getLockedAmountByAddress
code: function getLockedAmountByAddress(address _address) public view returns (uint256) {
    uint256 totalLockedAmount = 0;
    uint256[] memory tokenIds = walletOfOwner(_address);
    for (uint256 i = 0; i < tokenIds.length; i++) {
        totalLockedAmount += getLockedAmountByTokenId(tokenIds[i]);
    }
    return totalLockedAmount;
}
vulnerability: Staking lock bypass via NFT transfer
reason: The amount of NOVO considered locked for an address is computed solely from the staking NFTs currently owned by that address. ERC721 transfers are not hooked to update mapStakers or prevent transferring staking NFTs. A staker can mint an NFT with principalBalance equal to their NOVO balance, transfer the NFT to another address, and immediately have getLockedAmountByAddress(original) return zero. The original address can then transfer or sell the supposedly locked NOVO. The recipient of the NFT still has the stake accounting and can claim rewards or unstake, enabling fake stakes and reward dilution without actually locking tokens. This can be repeated by moving NFTs between addresses and reusing the same NOVO balance to create multiple apparent stakes.
------------------

